// TestRegistry_List_CacheOnly covers B3 (List returns all enabled modules in
// id order), B1 (Open reads arbitrary enabled rows, not just the TV seed), and
// INV2 (Get/List are cache-only: they keep serving after the modules table is
// wiped, proving no second database hit on the hot path).
func TestRegistry_List_CacheOnly(t *testing.T) {
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })

	// Seed a second enabled module so Open must read more than just the TV row.
	moviesCfg := `{"scanner":{"plugin_id":"base-scanner","capability_id":"default","options":{}}}`
	if _, err := s.DB().ExecContext(ctx, `INSERT OR IGNORE INTO modules
		(id, media_type, config_json, schema_version, enabled, created_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?)`,
		"movies", "movie", moviesCfg, 1, 1, "1970-01-01T00:00:00Z", "1970-01-01T00:00:00Z",
	); err != nil {
		t.Fatalf("insert movies: %v", err)
	}

	r, err := Open(ctx, s) // seeds tv + image + serial, loads image + movies + serial + tv
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}

	list, err := r.List()
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(list) != 4 {
		t.Fatalf("List = %d modules, want 4 (image+movies+serial+tv): %+v", len(list), list)
	}
	// id-ordered: "image" < "movies" < "serial" < "tv".
	if list[0].ID != "image" || list[1].ID != "movies" || list[2].ID != "serial" || list[3].ID != "tv" {
		t.Fatalf("List order = %s, %s, %s, %s; want image, movies, serial, tv",
			list[0].ID, list[1].ID, list[2].ID, list[3].ID)
	}

	// INV2: wipe the table; the cache must keep serving with no DB read.
	if _, err := s.DB().ExecContext(ctx, "DELETE FROM modules"); err != nil {
		t.Fatalf("delete modules: %v", err)
	}
	if _, err := r.Get("tv"); err != nil {
		t.Fatalf("Get(tv) after DB wipe = %v; cache must be independent of the DB (INV2)", err)
	}
	list2, err := r.List()
	if err != nil || len(list2) != 4 {
		t.Fatalf("List after DB wipe = %d (err=%v); want 4 (cache-only, INV2)", len(list2), err)
	}
}

// TestOpen_ImageSeeded covers the B2 image module seed (B01/B03): Open seeds an
// "image" module whose scanner binds base-scanner/default and whose
// metadata_sources contains exactly image-enricher (priority 1, enabled, local —
// no auth_mode). Get("image") resolves it; it is distinct from "tv".
func TestOpen_ImageSeeded(t *testing.T) {
	r, _ := openRegistry(t)

	m, err := r.Get("image")
	if err != nil {
		t.Fatalf("Get(image): %v", err)
	}
	if m.ID != "image" || m.MediaType != "image" || m.SchemaVersion != 1 {
		t.Fatalf("Get(image) = %+v, want id=image media_type=image schema_version=1", m)
	}
	if m.Scanner.PluginID != "base-scanner" || m.Scanner.CapabilityID != "default" {
		t.Fatalf("scanner binding = %+v, want base-scanner/default", m.Scanner)
	}
	if len(m.MetadataSources) != 1 {
		t.Fatalf("metadata_sources len = %d, want 1 (image-enricher only)", len(m.MetadataSources))
	}
	src := m.MetadataSources[0]
	if src.PluginID != "image-enricher" || src.CapabilityID != "default" {
		t.Errorf("metadata_source[0] = %+v, want image-enricher/default", src)
	}
	if src.Priority != 1 || !src.Enabled {
		t.Errorf("metadata_source[0] priority=%d enabled=%v, want priority=1 enabled=true", src.Priority, src.Enabled)
	}
	if src.AuthMode != "" {
		t.Errorf("metadata_source[0] auth_mode = %q, want empty (local parser; auth_mode would make it non-queueable per D-Q1)", src.AuthMode)
	}

	// TV module regression: the image seed did not alter the tv row (INSERT OR IGNORE).
	tv, err := r.Get("tv")
	if err != nil {
		t.Fatalf("Get(tv): %v", err)
	}
	if tv.ID != "tv" || tv.MediaType != "tv" {
		t.Fatalf("Get(tv) = %+v, want tv (image seed must not alter the tv row)", tv)
	}
}

// TestOpen_IdempotentSeedImage covers B04: running Open twice on the same store
// does not error and does not duplicate the image row (INSERT OR IGNORE).
func TestOpen_IdempotentSeedImage(t *testing.T) {
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })

	r1, err := Open(ctx, s)
	if err != nil {
		t.Fatalf("first Open: %v", err)
	}
	before := mustListLen(t, r1)

	if _, err := Open(ctx, s); err != nil {
		t.Fatalf("second Open: %v (INSERT OR IGNORE must keep re-Open error-free)", err)
	}
	r2, err := Open(ctx, s) // re-open the cache from the same rows
	if err != nil {
		t.Fatalf("third Open: %v", err)
	}
	if after := mustListLen(t, r2); after != before {
		t.Fatalf("List len after re-Open = %d, want %d (no duplicate seed rows)", after, before)
	}
	if _, err := r2.Get("image"); err != nil {
		t.Fatalf("Get(image) after re-Open = %v", err)
	}
}

// mustListLen returns the length of r.List (fails the test on error). Test helper.
func mustListLen(t *testing.T, r *Registry) int {
	t.Helper()
	list, err := r.List()
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	return len(list)
}

// TestSerialModuleSeed covers the serials-library module seed (box 1.1): Open
// seeds an idempotent "serial" config entity mirroring the tv seed shape —
// scanner binding serial-scanner/default with the "series-directories"
// structure knob, and the ordered metadata chain serial-parser (priority 1) +
// frame-grabber (priority 2) + shikimori (priority 3, enrichment D-7),
// media_type "serial" — while the seeded tv and
// image configs stay byte-identical. The two Go-consumed display view inputs
// (plugin-title-enrichment 1.2) decode into their exported Module fields.
func TestSerialModuleSeed(t *testing.T) {
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })

	r, err := Open(ctx, s)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}

	m, err := r.Get("serial")
	if err != nil {
		t.Fatalf("Get(serial): %v", err)
	}
	if m.ID != "serial" || m.MediaType != "serial" || m.SchemaVersion != 3 {
		t.Fatalf("Get(serial) = %+v, want id=serial media_type=serial schema_version=3", m)
	}
	if m.Scanner.PluginID != "serial-scanner" || m.Scanner.CapabilityID != "default" {
		t.Fatalf("scanner binding = %+v, want serial-scanner/default", m.Scanner)
	}
	var opts struct {
		Structure string `json:"structure"`
	}
	if err := json.Unmarshal(m.Scanner.Options, &opts); err != nil {
		t.Fatalf("parse scanner options: %v", err)
	}
	if opts.Structure != "series-directories" {
		t.Fatalf("options.structure = %q, want series-directories", opts.Structure)
	}
	if len(m.MetadataSources) != 3 {
		t.Fatalf("metadata_sources len = %d, want 3 (serial-parser + frame-grabber + shikimori)", len(m.MetadataSources))
	}
	for i, want := range []struct {
		pluginID string
		priority int
	}{
		{"serial-parser", 1},
		{"frame-grabber", 2},
		{"shikimori", 3},
	} {
		src := m.MetadataSources[i]
		if src.PluginID != want.pluginID || src.CapabilityID != "default" {
			t.Errorf("metadata_source[%d] = %+v, want %s/default", i, src, want.pluginID)
		}
		if src.Priority != want.priority || !src.Enabled {
			t.Errorf("metadata_source[%d] priority=%d enabled=%v, want priority=%d enabled=true",
				i, src.Priority, src.Enabled, want.priority)
		}
		if src.AuthMode != "" {
			t.Errorf("metadata_source[%d] auth_mode = %q, want empty (local plugin; queueable per D-Q1)",
				i, src.AuthMode)
		}
	}

	// The serial-parser binding declares the label-aware season_episode
	// composite (unified-parser 3.1): footer order title → season_episode →
	// parsed_from (the drift fix: serial-parser writes "title", not the
	// store-side display_title alias). identity_fields keep the raw season and
	// episode facts.
	wantDisplay := []string{"title", "season_episode", "parsed_from"}
	if got := m.MetadataSources[0].DisplayFields; !reflect.DeepEqual(got, wantDisplay) {
		t.Errorf("serial-parser display_fields = %v, want %v", got, wantDisplay)
	}

	// The two Go-consumed view inputs (plugin-title-enrichment 1.2): the
	// display block's language pick order and title-source walk decode into
	// exported Module fields; the remaining display keys stay SPA-consumed.
	wantLangPref := []string{"ru", "en"}
	if got := m.LanguagePreference; !reflect.DeepEqual(got, wantLangPref) {
		t.Errorf("language_preference = %v, want %v", got, wantLangPref)
	}
	wantTitlePriority := []string{"shikimori"}
	if got := m.TitleSourcePriority; !reflect.DeepEqual(got, wantTitlePriority) {
		t.Errorf("title_source_priority = %v, want %v", got, wantTitlePriority)
	}

	// The tv/image seeds are untouched by the serial addition: their persisted
	// config blobs are byte-identical to the seed constants (the serial seed
	// never rewrote them — INSERT OR IGNORE skips the existing rows).
	for id, want := range map[string]string{"tv": tvConfigJSON, "image": imageConfigJSON} {
		var got string
		if err := s.DB().QueryRowContext(ctx,
			"SELECT config_json FROM modules WHERE id = ?", id).Scan(&got); err != nil {
			t.Fatalf("load %s config: %v", id, err)
		}
		if got != want {
			t.Errorf("%s config_json differs from the %sConfigJSON seed constant (%d vs %d bytes)",
				id, id, len(got), len(want))
		}
	}

	// INSERT OR IGNORE: re-Open is error-free and does not duplicate the row.
	if _, err := Open(ctx, s); err != nil {
		t.Fatalf("re-Open: %v (serial seed must be idempotent)", err)
	}
	var n int
	if err := s.DB().QueryRowContext(ctx,
		"SELECT COUNT(*) FROM modules WHERE id = 'serial'").Scan(&n); err != nil {
		t.Fatalf("count serial rows: %v", err)
	}
	if n != 1 {
		t.Fatalf("serial seed rows = %d, want 1 (no duplicate after re-Open)", n)
	}
}

// TestPresentationFields covers the element-pages presentation declarations
// (box 1.1): every seeded module carries identity_fields and every declared
// parser binding carries its display_fields order — read back through the
// Registry accessors. AC-4: the declarations are config data; the core never
// branches on them.
func TestPresentationFields(t *testing.T) {
	r, _ := openRegistry(t)

	tests := []struct {
		name       string
		moduleID   string
		wantIdent  []string
		pluginID   string
		wantFields []string
	}{
		{
			name:       "tv identity + tv-parser order",
			moduleID:   "tv",
			wantIdent:  []string{"title", "year"},
			pluginID:   "tv-parser",
			wantFields: []string{"title", "year", "resolution", "parsed_from"},
		},
		{
			name:       "tv scanner binding order",
			moduleID:   "tv",
			wantIdent:  []string{"title", "year"},
			pluginID:   "base-scanner",
			wantFields: []string{"container", "duration", "video", "audio", "size"},
		},
		{
			name:       "serial identity + serial-parser order",
			moduleID:   "serial",
			wantIdent:  []string{"title", "season", "episode"},
			pluginID:   "serial-parser",
			wantFields: []string{"title", "season_episode", "parsed_from"},
		},
		{
			name:       "serial frame-grabber order",
			moduleID:   "serial",
			wantIdent:  []string{"title", "season", "episode"},
			pluginID:   "frame-grabber",
			wantFields: []string{"thumbnail", "grabbed_at"},
		},
		{
			name:       "image identity + image-enricher composite order",
			moduleID:   "image",
			wantIdent:  []string{"date_taken"},
			pluginID:   "image-enricher",
			wantFields: []string{"date_taken", "camera", "dimensions", "gps"},
		},
		{
			name:       "image scanner binding order",
			moduleID:   "image",
			wantIdent:  []string{"date_taken"},
			pluginID:   "base-scanner",
			wantFields: []string{"container", "duration", "video", "audio", "size"},
		},
		{
			name:       "seeded-but-unloaded parser declares no fields (pill only)",
			moduleID:   "tv",
			wantIdent:  []string{"title", "year"},
			pluginID:   "tmdb",
			wantFields: []string{},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ident, err := r.IdentityFields(tt.moduleID)
			if err != nil {
				t.Fatalf("IdentityFields(%s): %v", tt.moduleID, err)
			}
			if !reflect.DeepEqual(ident, tt.wantIdent) {
				t.Errorf("IdentityFields(%s) = %v, want %v", tt.moduleID, ident, tt.wantIdent)
			}
			fields, err := r.DisplayFields(tt.moduleID, tt.pluginID)
			if err != nil {
				t.Fatalf("DisplayFields(%s, %s): %v", tt.moduleID, tt.pluginID, err)
			}
			if !reflect.DeepEqual(fields, tt.wantFields) {
				t.Errorf("DisplayFields(%s, %s) = %v, want %v", tt.moduleID, tt.pluginID, fields, tt.wantFields)
			}
		})
	}

	// Accessor error cases: unknown module and unbound plugin both wrap
	// errNotFound; the declared order is exactly the seed order (the footer's
	// contract — config order IS render order).
	if _, err := r.IdentityFields("does-not-exist"); !errors.Is(err, errNotFound) {
		t.Errorf("IdentityFields(unknown) = %v, want errNotFound", err)
	}
	if _, err := r.DisplayFields("tv", "unbound-parser"); !errors.Is(err, errNotFound) {
		t.Errorf("DisplayFields(tv, unbound) = %v, want errNotFound", err)
	}
	fields, err := r.DisplayFields("tv", "tv-parser")
	if err != nil {
		t.Fatalf("DisplayFields(tv, tv-parser): %v", err)
	}
	want := []string{"title", "year", "resolution", "parsed_from"}
	for i, f := range want {
		if fields[i] != f {
			t.Fatalf("DisplayFields(tv, tv-parser) = %v, want declared order %v (config order IS footer render order)", fields, want)
		}
	}

	// Defensive copies: mutating a returned slice must not alias registry state.
	fields[0] = "mutated"
	again, err := r.DisplayFields("tv", "tv-parser")
	if err != nil {
		t.Fatalf("DisplayFields after caller mutation: %v", err)
	}
	if again[0] != "title" {
		t.Errorf("DisplayFields aliased registry state: got %v, want title first", again)
	}
}
